class ProductController {
    static Integer PAGE_SIZE = 9;

public

class Filters {
        @AuraEnabled

public String searchKey { get; set; }
        @AuraEnabled

public Decimal maxPrice { get; set; }
        @AuraEnabled

public String[] categories { get; set; }
        @AuraEnabled

public String[] materials { get; set; }
        @AuraEnabled

public String[] levels { get; set; }
    }

    @AuraEnabled(Cacheable=true scope='global')

public static PagedResult getProducts(Filters filters, Integer pageNumber) {
        String key, whereClause = '';
        Decimal maxPrice;
        String[] categories, materials, levels, criteria = new List<String>{};
        if (filters != null) {
        if (filters.categories == null) {
        criteria.add('Category__c = \'__NO_MATCH__\'');
    }
            maxPrice = filters.maxPrice;
            materials = filters.materials;
            levels = filters.levels;
            if (!String.isEmpty(filters.searchKey)) {
                key = '%' + filters.searchKey + '%';
                criteria.add('Name LIKE :key');
            }
            if (filters.maxPrice >= 0) {
                maxPrice = filters.maxPrice;
                criteria.add('MSRP__c <= :maxPrice');
            }
            if (filters.categories != null) {
                categories = filters.categories;
                criteria.add('Category__c IN :categories');
            }
            if (filters.levels != null) {
                levels = filters.levels;
                criteria.add('Level__c IN :levels');
            }
            if (filters.materials != null) {
                materials = filters.materials;
                criteria.add('Material__c IN :materials');
            }
            if (criteria.size() > 0) {
                whereClause = 'WHERE ' + String.join(criteria, ' AND ');
            }
        }

Integer pageSize = ProductController.PAGE_SIZE;
        Integer offset = (pageNumber - 1) * pageSize;
        PagedResult result = new PagedResult();
        result.pageSize = pageSize;
        result.pageNumber = pageNumber;
        result.totalItemCount = Database.countQuery(
            'SELECT count() FROM Product__c ' + whereClause
        );
        result.records = Database.query(
            'SELECT Id, Name, MSRP__c, Description__c, Category__c, Level__c, Picture_URL__c, Material__c FROM Product__c ' +
                whereClause +
                ' WITH USER_MODE' +
                ' ORDER BY Name LIMIT :pageSize OFFSET :offset'
        );
        return result;
    }

    @AuraEnabled(Cacheable=true scope='global')

public with sharing

class ProductRecordInfoController {
    @AuraEnabled(Cacheable=true scope='global')

public static List<String> getRecordInfo(String productOrFamilyName) {
        List<String> recordInfo = new List<String>();

        List<Product__c> cProductList = [
            SELECT ID
            FROM Product__c
            WHERE NAME = :productOrFamilyName
            WITH USER_MODE
        ];
        if (cProductList.size() > 0) {
            recordInfo.add(cProductList[0].ID);
            recordInfo.add('Product__c');
            return recordInfo;
        }

        List<Product_Family__c> cProductFamilyList = [
            SELECT ID
            FROM Product_Family__c
            WHERE NAME = :productOrFamilyName
            WITH USER_MODE
        ];
        if (cProductFamilyList.size() > 0) {
            recordInfo.add(cProductFamilyList[0].ID);
            recordInfo.add('Product_Family__c');
            return recordInfo;
        }
        return null;
    }
}

